
CREATE TABLE TUKUNAFUNC.AD_MAPEO_ERRORES (
    HTTP_STATUS NUMBER(3,0) NULL,
    ERROR_CATEGORY VARCHAR2(100 CHAR) NULL,
    INNER_DETAILS_FIELD_MESSAGE VARCHAR2(1000 CHAR) NULL,
    INNER_DETAILS_FIELD_MESSAGE_ES VARCHAR2(1000 CHAR) NULL,
    CURRENT_ERROR_CODE NUMBER(10,0) NOT NULL,
    CURRENT_ERROR_MESSAGE VARCHAR2(1000 CHAR) NULL,
    CURRENT_ERROR_MESSAGE_ES VARCHAR2(1000 CHAR) NULL,
    CONSTRAINT PK_AD_MAPEO_ERRORES PRIMARY KEY (CURRENT_ERROR_CODE)
);

-- Indices recomendados para busqueda por tipo/mensaje
