    ON TUKUNAFUNC.AD_MAPEO_ERRORES (ERROR_CATEGORY, CURRENT_ERROR_MESSAGE);

CREATE INDEX TUKUNAFUNC.IX_AD_MAPEO_ERR_CAT_INNER
